code_sketch:
const num = (value) => ({ kind: 'num', value });
const add = (left, right) => ({ kind: 'add', left, right });
function evalNode(n, ctx) {
  switch (n.kind) {
    case 'num': return n.value;
    case 'add': return evalNode(n.left, ctx) + evalNode(n.right, ctx);
    default: throw new Error(`unhandled node kind: ${n.kind}`);
  }
}

